    "src/interfaces/IMakinaXGovernable.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IMakinaXGovernable {
    /// @notice Operating modes of a module, ordered by increasing restriction.
    enum OperatingMode {
        OPEN,
        FENCED,
        WALLED
    }

    event GuardianAdded(address indexed newGuardian);
    event GuardianRemoved(address indexed guardian);
    event OperatingModeChanged(OperatingMode indexed mode);
    event OperatorAdded(address indexed newOperator);
    event OperatorRemoved(address indexed operator);
    event Paused(address indexed guardian);
    event Unpaused(address indexed guardian);
    event ProviderChanged(address indexed oldProvider, address indexed newProvider);
    event Suspended();
    event Unsuspended();

    /// @notice Address of the Safe.
    function safe() external view returns (address);

    /// @notice Address of the MakinaX service account.
    function provider() external view returns (address);

    /// @notice Account => Whether the account is an operator.
    function isOperator(address account) external view returns (bool);

    /// @notice Account => Whether the account is a guardian.
    function isGuardian(address account) external view returns (bool);

    /// @notice Current operating mode of the contract.
    function operatingMode() external view returns (OperatingMode);

    /// @notice True if the contract is suspended by the provider, false otherwise.
    function suspendedByProvider() external view returns (bool);

    /// @notice True if the contract is paused by a guardian, false otherwise.
    function paused() external view returns (bool);

    /// @notice Sets the provider address.
    /// @param newProvider The address of the new provider.
    function setProvider(address newProvider) external;

    /// @notice Adds a new operator.
    /// @param newOperator The address of the new operator.
    function addOperator(address newOperator) external;

    /// @notice Removes an operator.
    /// @param operator The address of the operator to remove.
    function removeOperator(address operator) external;

    /// @notice Adds a new guardian.
    /// @param newGuardian The address of the new guardian.
    function addGuardian(address newGuardian) external;

    /// @notice Removes a guardian.
    /// @param guardian The address of the guardian to remove.
    function removeGuardian(address guardian) external;

    /// @notice Sets the operating mode.
    /// @param newMode The operating mode to set.
    function setOperatingMode(OperatingMode newMode) external;

    /// @notice Suspends operations. Used by the provider to enforce service restrictions.
    function suspend() external;

    /// @notice Restores operations after a provider suspension.
    function unsuspend() external;

    /// @notice Pauses operations. Used by a guardian in case of emergency.
    function pause() external;

    /// @notice Unpauses operations after an emergency pause.
    function unpause() external;
}
"
    },
    "src/interfaces/IOracleRegistry.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice An aggregator of Chainlink price feeds that prices tokens in a reference currency (e.g., USD) using up to two feeds.
/// If a direct feed between a base token and the reference currency does not exist, it combines two feeds to compute the price.
///
/// Example:
/// To price Token A in Token B:
/// - If a feed for Token A -> Reference Currency exists, the registry uses that feed.
/// - If Token B lacks a direct feed to the Reference Currency, but feeds for Token B -> Intermediate Token and
///   Intermediate Token -> Reference Currency exist, the registry combines these feeds to derive the price.
/// - Finally, the price Token A -> Token B is calculated using both tokens' individual prices in the reference currency.
///
interface IOracleRegistry {
    event FeedRouteCleared(address indexed token);
    event FeedRouteRegistered(address indexed token, address indexed feed1, address indexed feed2);
    event FeedStaleThresholdChanged(address indexed feed, uint256 oldThreshold, uint256 newThreshold);

    struct FeedRoute {
        address feed1;
        address feed2;
    }

    /// @notice Feed => Staleness threshold in seconds
    function getFeedStaleThreshold(address feed) external view returns (uint256);

    /// @notice Token => Is feed route registered for the token
    function isFeedRouteRegistered(address token) external view returns (bool);

    /// @notice Gets the price feed route for a given token.
    /// @param token The address of the token for which the price feed route is requested.
    /// @return feed1 The address of the first price feed.
    /// @return feed2 The address of the optional second price feed.
    function getFeedRoute(address token) external view returns (address, address);

    /// @notice Returns the price of one unit of the given token in terms of the reference currency.
    /// @param baseToken The address of the token for which the price is requested.
    /// @return price The price of baseToken denominated in the reference currency (expressed in 18 decimals).
    function getReferencePrice(address baseToken) external view returns (uint256);

    /// @notice Returns the price of one unit of baseToken in terms of quoteToken.
    /// @param baseToken The address of the token for which the price is requested.
    /// @param quoteToken The address of the token in which the price is quoted.
    /// @return price The price of baseToken denominated in quoteToken (expressed in quoteToken decimals).
    function getPrice(address baseToken, address quoteToken) external view returns (uint256);

    /// @notice Sets the price feed route for a given token.
    /// @dev Both feeds, if set, must be Chainlink-interface-compliant.
    /// The combination of feed1 and feed2 must be able to price the token in the reference currency.
    /// If feed2 is set to address(0), the token price in the reference currency is assumed to be returned by feed1.
    /// @param token The address of the token for which the price feed route is set.
    /// @param feed1 The address of the first price feed.
    /// @param stalenessThreshold1 The staleness threshold for the first price feed.
    /// @param feed2 The address of the second price feed. Can be set to address(0).
    /// @param stalenessThreshold2 The staleness threshold for the second price feed. Ignored if feed2 is address(0).
    function setFeedRoute(
        address token,
        address feed1,
        uint256 stalenessThreshold1,
        address feed2,
        uint256 stalenessThreshold2
    ) external;

    /// @notice Clears the price feed route for a given token.
    /// @dev Staleness thresholds for the route's feeds are preserved, as the feeds may be used by other routes.
    /// @param token The address of the token for which the price feed route is cleared.
    function clearFeedRoute(address token) external;

    /// @notice Sets the price staleness threshold for a given feed.
    /// @param feed The address of the price feed.
    /// @param newThreshold The value of staleness threshold.
    function setFeedStaleThreshold(address feed, uint256 newThreshold) external;
}
"
    },
    "src/interfaces/ISwapComponent.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface ISwapComponent {
    event MaxSwapLossBpsChanged(uint256 oldMaxSwapLossBps, uint256 newMaxSwapLossBps);
    event Swap(
        uint16 indexed swapperId,
        address indexed inputToken,
        address indexed outputToken,
        uint256 inputAmount,
        uint256 outputAmount
    );
    event SwapCooldownDurationChanged(uint256 oldSwapCooldownDuration, uint256 newSwapCooldownDuration);
    event SwapFeeRateChanged(uint256 oldSwapFeeRate, uint256 newSwapFeeRate);
    event SwapperTargetsSet(uint16 indexed swapperId, address approvalTarget, address executionTarget);

    struct SwapperTargets {
        address approvalTarget;
        address executionTarget;
    }

    /// @notice Generic swap params.
    /// @param swapperId The ID of the external swap protocol.
    /// @param data The swap calldata to pass to the swapper's execution target.
    /// @param inputToken The input token.
    /// @param outputToken The output token.
    /// @param inputAmount The input amount.
    /// @param minOutputAmount The minimum expected output amount.
    struct SwapOrder {
        uint16 swapperId;
        bytes data;
        address inputToken;
        address outputToken;
        uint256 inputAmount;
        uint256 minOutputAmount;
    }

    /// @notice Max allowed value loss (in basis points) for token swaps while in FENCED or WALLED mode.
    function maxSwapLossBps() external view returns (uint256);

    /// @notice Cooldown duration (in seconds) for token swaps while in FENCED or WALLED mode.
    function swapCooldownDuration() external view returns (uint256);

    /// @notice Swap fee rate, 1e18 = 100%.
    function swapFeeRate() external view returns (uint256);

    /// @notice Returns approval and execution targets for a given swapper ID.
    /// @param swapperId The swapper ID.
    /// @return approvalTarget The approval target.
    /// @return executionTarget The execution target.
    function getSwapperTargets(uint16 swapperId) external view returns (address approvalTarget, address executionTarget);

    /// @notice Swaps tokens on behalf of the Safe using a given swapper.
    /// @param order The swap params.
    function swap(SwapOrder calldata order) external;

    /// @notice Sets the maximum allowed relative value loss for token swaps while in FENCED or WALLED mode.
    /// @param newMaxSwapLossBps The new maximum value loss in basis points.
    function setMaxSwapLossBps(uint256 newMaxSwapLossBps) external;

    /// @notice Sets the cooldown duration for token swaps while in FENCED or WALLED mode.
    /// @param newSwapCooldownDuration The new cooldown duration in seconds.
    function setSwapCooldownDuration(uint256 newSwapCooldownDuration) external;

    /// @notice Sets the swap fee rate.
    /// @param newSwapFeeRate The new swap fee rate, 1e18 = 100%.
    function setSwapFeeRate(uint256 newSwapFeeRate) external;

    /// @notice Sets approval and execution targets for a given swapper ID.
    /// @param swapperId The swapper ID.
    /// @param approvalTarget The approval target.
    /// @param executionTarget The execution target.
    function setSwapperTargets(uint16 swapperId, address approvalTarget, address executionTarget) external;
}
"
    },
    "src/interfaces/IWeirollComponent.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ISwapComponent} from "./ISwapComponent.sol";

interface IWeirollComponent {
    event AllowedInstrRootChanged(bytes32 indexed oldRoot, bytes32 indexed newRoot);
    event AccountingCurrencyChanged(address indexed oldAccountingCurrency, address indexed newAccountingCurrency);
    event InstrCooldownDurationChanged(uint256 oldInstrCooldownDuration, uint256 newInstrCooldownDuration);
    event MaxPositionIncreaseLossBpsChanged(
        uint256 oldMaxPositionIncreaseLossBps, uint256 newMaxPositionIncreaseLossBps
    );
    event MaxPositionDecreaseLossBpsChanged(
        uint256 oldMaxPositionDecreaseLossBps, uint256 newMaxPositionDecreaseLossBps
    );
    event PositionManaged(bool indexed withValuation, bool indexed guarded, uint256 indexed positionId, uint256 value);

    enum InstructionType {
        MANAGEMENT,
        ACCOUNTING,
        HARVEST,
        FLASHLOAN_MANAGEMENT
    }

    /// @notice Instruction parameters.
    /// @param positionId The ID of the involved position.
    /// @param isDebt Whether the position is a debt.
    /// @param groupId The ID of the position accounting group.
    ///        Set to 0 if the instruction is not of type ACCOUNTING, or if the involved position is ungrouped.
    /// @param instructionType The type of the instruction.
    /// @param affectedTokens The array of affected tokens.
    /// @param positionTokens The array of position tokens.
    /// @param commands The array of commands.
    /// @param state The array of state.
    /// @param stateBitmap The state bitmap.
    /// @param merkleProof The array of Merkle proof elements.
    struct Instruction {
        uint256 positionId;
        bool isDebt;
        uint256 groupId;
        InstructionType instructionType;
        address[] affectedTokens;
        address[] positionTokens;
        bytes32[] commands;
        bytes[] state;
        uint128 stateBitmap;
        bytes32[] merkleProof;
    }

    /// @notice Address of the Weiroll VM.
    function weirollVm() external view returns (address);

    /// @notice Root of the Merkle tree containing allowed instructions.
    function allowedInstrRoot() external view returns (bytes32);

    /// @notice Currency used to value positions.
    /// @dev If set to address(0), the reference currency of the OracleRegistry is used.
    function accountingCurrency() external view returns (address);

    /// @notice Max allowed value loss (in basis points) when increasing a position while in WALLED mode.
    function maxPositionIncreaseLossBps() external view returns (uint256);

    /// @notice Max allowed value loss (in basis points) when decreasing a position while in WALLED mode.
    function maxPositionDecreaseLossBps() external view returns (uint256);

    /// @notice Cooldown duration for instruction executions in seconds.
    function instrCooldownDuration() external view returns (uint256);

    /// @notice Prices a position.
    /// @param instruction The accounting instruction.
    /// @return value The new position value.
    function accountForPosition(Instruction calldata instruction) external returns (uint256 value);

    /// @notice Prices a batch of positions.
    /// @param instructions The array of accounting instructions.
    /// @param groupIds Ignored parameter kept to preserve interface compatibility with Makina Core.
    /// @return values The new position values.
    function accountForPositionBatch(Instruction[] calldata instructions, uint256[] calldata groupIds)
        external
        returns (uint256[] memory values);

    /// @notice Manages a position's state through paired management and accounting instructions.
    /// @dev If `acctInstruction` is provided, it is executed before and after the management instruction to
    /// compute the new position value and its signed delta.
    /// @dev In WALLED mode, `acctInstruction` must be provided and value preservation checks are applied using
    /// a validation matrix to prevent economic inconsistencies between position changes and token flows.
    ///
    /// The WALLED mode matrix evaluates three factors to determine required validations:
    /// - Affected Tokens flow - Sign of the change in the Safe's aggregate value of `mgmtInstruction.affectedTokens`
    /// - Debt Position - Whether position represents protocol liability (true) vs asset (false)
    /// - Position Δ direction - Direction of position value change (increase/decrease/null)
    ///
    /// ┌──────────────────────┬───────────────┬──────────────────────┬───────────────────────────┐
    /// │ Affected Tokens flow │ Debt Position │ Position Δ direction │ Action                    │
    /// ├──────────────────────┼───────────────┼──────────────────────┼───────────────────────────┤
    /// │ Outflow              │ No            │ Decrease             │ Revert: Invalid direction │
    /// │ Outflow              │ Yes           │ Increase             │ Revert: Invalid direction │
    /// │ Outflow              │ No            │ Increase / Null      │ Minimum Δ Check           │
    /// │ Outflow              │ Yes           │ Decrease / Null      │ Minimum Δ Check           │
    /// │ Inflow / Null        │ No            │ Decrease             │ Maximum Δ Check           │
    /// │ Inflow / Null        │ Yes           │ Increase             │ Maximum Δ Check           │
    /// │ Inflow / Null        │ No            │ Increase / Null      │ No check (favorable move) │
    /// │ Inflow / Null        │ Yes           │ Decrease / Null      │ No check (favorable move) │
    /// └──────────────────────┴───────────────┴──────────────────────┴───────────────────────────┘
    ///
    /// @param mgmtInstruction The management instruction.
    /// @param acctInstruction The accounting instruction.
    /// @return value The new position value, or 0 if `acctInstruction` was not provided.
    /// @return change The signed position value delta, or 0 if `acctInstruction` was not provided.
    function managePosition(Instruction calldata mgmtInstruction, Instruction calldata acctInstruction)
        external
        returns (uint256 value, int256 change);

    /// @notice Manages a batch of positions.
    /// @dev Convenience function to manage multiple positions in a single transaction.
    /// @param mgmtInstructions The array of management instructions.
    /// @param acctInstructions The array of accounting instructions.
    /// @return values The new position values.
    /// @return changes The changes in the position values.
    function managePositionBatch(Instruction[] calldata mgmtInstructions, Instruction[] calldata acctInstructions)
        external
        returns (uint256[] memory values, int256[] memory changes);

    /// @notice Manages flash loan funds.
    /// @param instruction The flash loan management instruction.
    /// @param token The loan token.
    /// @param amount The loan amount.
    function manageFlashLoan(Instruction calldata instruction, address token, uint256 amount) external;

    /// @notice Harvests one or multiple positions.
    /// @param instruction The harvest instruction.
    /// @param swapOrders The array of swap orders to be executed after the harvest.
    function harvest(Instruction calldata instruction, ISwapComponent.SwapOrder[] calldata swapOrders) external;

    /// @notice Sets the root of the Merkle tree containing allowed instructions.
    /// @param newAllowedInstrRoot The new Merkle root.
    function setAllowedInstrRoot(bytes32 newAllowedInstrRoot) external;

    /// @notice Sets the currency used to value positions.
    /// @param newAccountingCurrency The new currency.
    function setAccountingCurrency(address newAccountingCurrency) external;

    /// @notice Sets the maximum allowed relative value loss for position increases while in WALLED mode.
    /// @param newMaxPositionIncreaseLossBps The new maximum value loss in basis points.
    function setMaxPositionIncreaseLossBps(uint256 newMaxPositionIncreaseLossBps) external;

    /// @notice Sets the maximum allowed relative value loss for position decreases while in WALLED mode.
    /// @param newMaxPositionDecreaseLossBps The new maximum value loss in basis points.
    function setMaxPositionDecreaseLossBps(uint256 newMaxPositionDecreaseLossBps) external;

    /// @notice Sets the cooldown duration for instruction executions while in WALLED mode.
    /// @param newInstrCooldownDuration The new cooldown duration in seconds.
    function setInstrCooldownDuration(uint256 newInstrCooldownDuration) external;
}
"
    },
